<template><section aria-label="病例去标识独立模式入口"><p v-if="!boundaryValid" role="alert">病例去标识只接受当前第75项、实际患者绑定和唯一Case引用；其它来源引用、就诊范围或协议模式已拒绝，不退回通用模型。</p><DeidentificationSharedAssistant v-else :key="fingerprint" :feature="feature" :scope="null" :patient-id="patientId" :initial-references="references" :initial-question="initialInput.question" :active="active"/></section></template>
<script setup>
import{computed}from'vue';import{useStore}from'vuex';import DeidentificationSharedAssistant from'./DeidentificationSharedAssistant.vue';import{deidentificationTaskInputValid}from'@/api/ai/deidentificationTasks';import{deidentificationCanonical as canonical,positive,keys}from'@/api/ai/deidentificationCore';
const props=defineProps({feature:{type:Object,default:null},featureKey:{type:String,default:'deidentification'},initialInput:{type:Object,default:()=>({})},patientId:{type:Number,default:null},encounterRef:{type:String,default:null},pharmaceuticalId:{type:Number,default:null},active:{type:Boolean,default:true}}),store=useStore();
const boundaryValid=computed(()=>{const v=props.initialInput;if(props.featureKey!=='deidentification'||props.feature?.key!=='deidentification'||props.feature.engine!=='llm'||props.feature.scope!=='hospital'||props.feature.input_mode!=='deidentification_evidence'||props.encounterRef!==null&&props.encounterRef!==''||props.pharmaceuticalId!==null||props.patientId!==null&&!positive(props.patientId)||v===null||typeof v!=='object'||Array.isArray(v)||Object.keys(v).some(k=>!['deidentification_case_id','question'].includes(k)))return false;if(Object.hasOwn(v,'deidentification_case_id'))return deidentificationTaskInputValid(v);return keys(v,[]);}),references=computed(()=>Object.hasOwn(props.initialInput,'deidentification_case_id')?{deidentification_case_id:props.initialInput.deidentification_case_id}:null),fingerprint=computed(()=>canonical([props.featureKey,props.feature,props.initialInput,props.patientId,props.encounterRef,props.pharmaceuticalId,props.active,store.state.user?.accessToken,store.state.user?.username,store.state.user?.permissions]));
</script>
